#!/usr/bin/env python3
"""Finalize: LP dispatch with fixed commitment, independent verification, write report.json"""
import json
import pulp

d = json.load(open('network.json'))
T = d['time_periods']
demand = d['demand']
reserves = d['reserves']
TH = d['thermal_generators']
RN = d['renewable_generators']
th_names = list(TH.keys())
rn_names = list(RN.keys())

C = json.load(open('commitment2.json'))
U = C['U']; SU = C['SU']; SD = C['SD']
mip_obj = C['obj']; mip_bound = C['bound']; solver_status = C['solver_status']; gap = C['gap']

# fix commitment
prob = pulp.LpProblem('dispatch', pulp.LpMinimize)
p = {}; r = {}; rp = {}
for n in th_names:
    g = TH[n]
    pp = g['piecewise_production']
    slopes = [(pp[k+1]['cost'] - pp[k]['cost']) / (pp[k+1]['mw'] - pp[k]['mw']) for k in range(len(pp)-1)]
    c1 = pp[0]['cost']
    for t in range(T):
        p[n, t] = pulp.LpVariable(f'p_{n}_{t}', lowBound=0, upBound=g['power_output_maximum'] * U[n][t])
        r[n, t] = pulp.LpVariable(f'r_{n}_{t}', lowBound=0)
        # production cost expression (convex incremental) via helper constraints
for n in rn_names:
    mn = RN[n]['power_output_minimum']; mx = RN[n]['power_output_maximum']
    rp[n] = [pulp.LpVariable(f'rp_{n}_{t}', lowBound=mn[t], upBound=mx[t]) for t in range(T)]

# cost via epigraph on convex piecewise (exact since convex): use incremental deltas
seg = {}
for n in th_names:
    g = TH[n]
    pp = g['piecewise_production']
    widths = [pp[k+1]['mw'] - pp[k]['mw'] for k in range(len(pp)-1)]
    seg[n] = {}
    for t in range(T):
        seg[n][t] = [pulp.LpVariable(f'seg_{n}_{t}_{k}', lowBound=0, upBound=widths[k])
                     for k in range(len(widths))]

obj_terms = []
for n in th_names:
    g = TH[n]
    pp = g['piecewise_production']
    slopes = [(pp[k+1]['cost'] - pp[k]['cost']) / (pp[k+1]['mw'] - pp[k]['mw']) for k in range(len(pp)-1)]
    c1 = pp[0]['cost']
    for t in range(T):
        obj_terms.append(c1 * U[n][t])
        for k in range(len(slopes)):
            obj_terms.append(slopes[k] * seg[n][t][k])
        # link
        prob += p[n, t] == g['power_output_minimum'] * U[n][t] + pulp.lpSum(seg[n][t])
        prob += p[n, t] >= g['power_output_minimum'] * U[n][t]
        prob += p[n, t] + r[n, t] <= g['power_output_maximum'] * U[n][t]
        if U[n][t] == 0:
            prob += r[n, t] <= 0
        # ramping
        RSU, RSD = g['ramp_startup_limit'], g['ramp_shutdown_limit']
        RU, RD = g['ramp_up_limit'], g['ramp_down_limit']
        if t == 0:
            prev_p = g['power_output_t0']; prev_u = g['unit_on_t0']
        else:
            prev_p = p[n, t-1]; prev_u = U[n][t-1]
        prob += p[n, t] - prev_p <= RU * prev_u + RSU * SU[n][t]
        prob += prev_p - p[n, t] <= RD * U[n][t] + RSD * SD[n][t]
for t in range(T):
    prob += (pulp.lpSum(p[n, t] for n in th_names) +
             pulp.lpSum(rp[n][t] for n in rn_names)) == demand[t]
    prob += pulp.lpSum(r[n, t] for n in th_names) >= reserves[t]
prob += pulp.lpSum(obj_terms)

import highspy
prob.writeLP('dispatch.lp')
h = highspy.Highs()
h.setOptionValue('output_flag', False)
h.readModel('dispatch.lp')
h.run()
st = h.modelStatusToString(h.getModelStatus())
print('LP status:', st)
sol = h.getSolution(); val = dict(zip([str(x) for x in lp_names] if False else list(h.getLp().col_names_), list(sol.col_value)))

P = {n: [val[f'p_{n}_{t}'] for t in range(T)] for n in th_names}
R = {n: [val[f'r_{n}_{t}'] for t in range(T)] for n in th_names}
RP = {n: [val[f'rp_{n}_{t}'] for t in range(T)] for n in rn_names}

# clean numerical noise: exact balance via curtailable renewables
for t in range(T):
    resid = demand[t] - sum(P[n][t] for n in th_names) - sum(RP[n][t] for n in rn_names)
    if abs(resid) > 1e-7:
        for n in rn_names:
            mn = RN[n]['power_output_minimum'][t]; mx = RN[n]['power_output_maximum'][t]
            if mx - mn > 1e-6:
                newv = RP[n][t] + resid
                if mn - 1e-9 <= newv <= mx + 1e-9:
                    RP[n][t] = min(max(newv, mn), mx)
                    resid = demand[t] - sum(P[nn][t] for nn in th_names) - sum(RP[nn][t] for nn in rn_names)
                    if abs(resid) < 1e-7:
                        break
    assert abs(resid) < 1e-5, (t, resid)

# clean tiny values
for n in th_names:
    for t in range(T):
        if U[n][t] == 0:
            P[n][t] = 0.0; R[n][t] = 0.0
        else:
            P[n][t] = max(P[n][t], TH[n]['power_output_minimum'])
            if P[n][t] < 1e-9: P[n][t] = 0.0
            if R[n][t] < 1e-9: R[n][t] = 0.0
            # clip to limits
            P[n][t] = min(max(P[n][t], TH[n]['power_output_minimum']), TH[n]['power_output_maximum'])
            R[n][t] = min(R[n][t], TH[n]['power_output_maximum'] - P[n][t])

# ---------------- independent verification ----------------
def interp(pp, x):
    for a, b in zip(pp, pp[1:]):
        if a['mw'] <= x <= b['mw'] + 1e-9:
            if b['mw'] == a['mw']:
                return a['cost']
            return a['cost'] + (b['cost'] - a['cost']) * (x - a['mw']) / (b['mw'] - a['mw'])
    return pp[-1]['cost']

fails = []
def chk(name, cond, msg=''):
    if not cond:
        fails.append(f'{name}: {msg}')

# 1) demand balance
max_bal = max(abs(sum(P[n][t] for n in th_names) + sum(RP[n][t] for n in rn_names) - demand[t]) for t in range(T))
# 2) reserve
max_res_short = max(max(0.0, reserves[t] - sum(R[n][t] for n in th_names)) for t in range(T))
# 3) per-unit checks
total_su = 0; total_sd = 0; total_cost = 0.0
for n in th_names:
    g = TH[n]
    pmin, pmax = g['power_output_minimum'], g['power_output_maximum']
    RU, RD = g['ramp_up_limit'], g['ramp_down_limit']
    RSU, RSD = g['ramp_startup_limit'], g['ramp_shutdown_limit']
    UT, DT = g['time_up_minimum'], g['time_down_minimum']
    on0, p0 = g['unit_on_t0'], g['power_output_t0']
    up0, dn0 = g['time_up_t0'], g['time_down_t0']
    u = U[n]; su = SU[n]; sd = SD[n]
    # commitment arrays consistent with su/sd
    for t in range(T):
        pu = u[t-1] if t >= 1 else on0
        chk('logic', su[t] - sd[t] == u[t] - pu, f'{n} t{t}')
        chk('susd', su[t] + sd[t] <= 1, f'{n} t{t}')
        total_su += su[t]; total_sd += sd[t]
    # limits
    for t in range(T):
        if u[t] == 0:
            chk('limits', P[n][t] == 0 and R[n][t] == 0, f'{n} t{t} off but p={P[n][t]}')
        else:
            chk('limits', pmin - 1e-6 <= P[n][t] <= pmax + 1e-6, f'{n} t{t} p={P[n][t]}')
            chk('limits', R[n][t] >= -1e-6 and R[n][t] <= pmax - P[n][t] + 1e-6, f'{n} t{t} r={R[n][t]}')
    # ramp
    for t in range(T):
        if t == 0:
            prev_p, prev_u = p0, on0
        else:
            prev_p, prev_u = P[n][t-1], u[t-1]
        chk('ramp', P[n][t] - prev_p <= RU * prev_u + RSU * su[t] + 1e-5, f'{n} t{t} up')
        chk('ramp', prev_p - P[n][t] <= RD * u[t] + RSD * sd[t] + 1e-5, f'{n} t{t} dn')
    # min up / min down
    for t in range(T):
        if su[t] == 1:
            for j in range(t, min(T, t + UT)):
                chk('minupdown', u[j] == 1, f'{n} startup t{t} minup violated j={j}')
        if sd[t] == 1:
            for j in range(t, min(T, t + DT)):
                chk('minupdown', u[j] == 0, f'{n} shutdown t{t} mindown violated j={j}')
    # initial conditions
    if on0 == 1 and up0 < UT:
        for j in range(UT - up0):
            chk('init', u[j] == 1, f'{n} init minup')
    if on0 == 0 and dn0 < DT:
        for j in range(DT - dn0):
            chk('init', u[j] == 0, f'{n} init mindown')
    if g['must_run'] == 1:
        chk('mustrun', all(u[t] == 1 for t in range(T)), n)
    # cost
    for t in range(T):
        if u[t] == 1:
            total_cost += interp(g['piecewise_production'], P[n][t])
    # startup cost by downtime tier
    for t in range(T):
        if su[t] == 1:
            # last shutdown hour
            s = None
            for i in range(t - 1, -1, -1):
                if sd[i] == 1:
                    s = i; break
            if s is None and on0 == 0:
                downtime = t - (1 - dn0)
            elif s is None:
                downtime = None
            else:
                downtime = t - s
            chk('startcost', downtime is not None, f'{n} t{t} no downtime origin')
            tiers = g['startup']
            cost_tier = None
            for s_ in tiers:
                if downtime >= s_['lag']:
                    cost_tier = s_['cost']
            chk('startcost', cost_tier is not None, f'{n} t{t} downtime {downtime} < min lag')
            if cost_tier:
                total_cost += cost_tier

# renewable limits
for n in rn_names:
    mn = RN[n]['power_output_minimum']; mx = RN[n]['power_output_maximum']
    for t in range(T):
        chk('renlim', mn[t] - 1e-6 <= RP[n][t] <= mx[t] + 1e-6, f'{n} t{t} {RP[n][t]}')

print('max balance viol:', max_bal)
print('max reserve shortfall:', max_res_short)
print('total startups:', total_su, 'shutdowns:', total_sd)
print('recomputed cost:', total_cost, 'mip obj:', mip_obj)
print('FAILS:', fails if fails else 'none')

assert not fails, fails[:20]
assert max_bal < 1e-5 and max_res_short < 1e-5

# ---------------- write report ----------------
report = {
    "case_name": "unit_commitment_schedule",
    "summary": {
        "solver_status": solver_status,
        "objective_cost": round(total_cost, 2),
        "reported_mip_gap": round(gap, 6) if gap is not None else None,
        "time_periods": T,
        "num_thermal_generators": len(th_names),
        "num_renewable_generators": len(rn_names),
        "total_startups": total_su,
        "total_shutdowns": total_sd,
        "max_demand_balance_violation_MW": round(max_bal, 9),
        "max_reserve_shortfall_MW": round(max_res_short, 9)
    },
    "thermal_generators": [
        {
            "name": n,
            "commitment": U[n],
            "production_MW": [round(x, 6) for x in P[n]],
            "reserve_MW": [round(x, 6) for x in R[n]],
            "startup": SU[n],
            "shutdown": SD[n]
        } for n in th_names
    ],
    "renewable_generators": [
        {
            "name": n,
            "production_MW": [round(x, 6) for x in RP[n]]
        } for n in rn_names
    ],
    "hourly_summary": [
        {
            "hour": t + 1,
            "demand_MW": demand[t],
            "thermal_generation_MW": round(sum(P[n][t] for n in th_names), 6),
            "renewable_generation_MW": round(sum(RP[n][t] for n in rn_names), 6),
            "reserve_requirement_MW": reserves[t],
            "scheduled_spinning_reserve_MW": round(sum(R[n][t] for n in th_names), 6)
        } for t in range(T)
    ],
    "constraint_check": {
        "demand_balance": "pass",
        "spinning_reserve": "pass",
