        # reserve: headroom + ramp-rate deliverability + ramp-coupled deliverability
        prob += p[n, t] + r[n, t] <= pmax * U[n][t]
        prob += r[n, t] <= RU
        if SU[n][t] == 1 or SD[n][t] == 1:
