python3 - <<'EOF'
import json
d = json.load(open('network.json'))
r = json.load(open('report.json'))
TH = d['thermal_generators']; T = d['time_periods']
reserves = d['reserves']

cats = {}
def add(cat, msg):
    cats.setdefault(cat, []).append(msg)

for tg in r['thermal_generators']:
    n = tg['name']; g = TH[n]
    pmin, pmax = g['power_output_minimum'], g['power_output_maximum']
    RU, RD = g['ramp_up_limit'], g['ramp_down_limit']
    RSU, RSD = g['ramp_startup_limit'], g['ramp_shutdown_limit']
    on0, p0 = g['unit_on_t0'], g['power_output_t0']
    u, p, rr, su, sd = tg['commitment'], tg['production_MW'], tg['reserve_MW'], tg['startup'], tg['shutdown']
    for t in range(T):
        if u[t] == 0:
            if p[t] != 0 or rr[t] != 0: add('R1', f'{n} {t}')
            continue
        if not (pmin - 1e-6 <= p[t] <= pmax + 1e-6): add('R2', f'{n} {t} {p[t]}')
        if rr[t] > pmax - p[t] + 1e-6: add('R3', f'{n} {t} {rr[t]}')
        if rr[t] > RU + 1e-6: add('R4', f'{n} {t} {rr[t]}>{RU}')
        if rr[t] > RD + 1e-6: add('R5', f'{n} {t}')
        prev_p = p0 if t == 0 else p[t-1]
        prev_u = on0 if t == 0 else u[t-1]
        prev_r = 0.0 if t == 0 else rr[t-1]
        if prev_u == 1 and u[t] == 1 and su[t] == 0:
            if p[t] - prev_p > RU + 1e-5: add('R6', f'{n} {t}')
            if prev_p - p[t] > RD + 1e-5: add('R7', f'{n} {t}')
        if su[t] == 1:
            if p[t] > RSU + 1e-5: add('R8a', f'{n} {t} {p[t]}>{RSU}')
            if p[t] + rr[t] > RSU + 1e-5: add('R8b', f'{n} {t}')
        if sd[t] == 1 and prev_p > RSD + 1e-5: add('R9', f'{n} {t} {prev_p}>{RSD}')
        # coupled from prev output (online prev)
        if prev_u == 1 and u[t] == 1:
            if p[t] + rr[t] > prev_p + RU + 1e-5: add('R10', f'{n} {t}')
        if t == 0 and on0 == 1:
            if p[0] + rr[0] > p0 + RU + 1e-5: add('R11a', f'{n} 0')
            if p[0] - p0 > RU + 1e-5: add('R11b', f'{n} 0')
            if p0 - p[0] > RD + 1e-5: add('R11c', f'{n} 0')
        if (su[t] == 1 or sd[t] == 1) and rr[t] != 0: add('R13', f'{n} {t}')
        if t >= 1:
            if rr[t] - rr[t-1] > RU + 1e-5: add('R14a', f'{n} {t}')
            if rr[t-1] - rr[t] > RD + 1e-5: add('R14b', f'{n} {t}')
            if p[t] + rr[t] > prev_p + prev_r + RU + 1e-5: add('R15', f'{n} {t}')
        if rr[t] > RU/2 + 1e-6: add('R16a', f'{n} {t} {rr[t]}>{RU/2:.2f}')
        if rr[t] > RU/6 + 1e-6: add('R16b', f'{n} {t} {rr[t]}>{RU/6:.2f}')

# system reserve equality
for t in range(T):
    tot = sum(tg['reserve_MW'][t] for tg in r['thermal_generators'])
    if abs(tot - reserves[t]) > 1e-6: add('Req', f'{t} {tot} vs {reserves[t]}')

for c in sorted(cats):
    print(c, len(cats[c]), cats[c][:4])
if not cats: print('no violations of R1-R16')
# which units start during horizon
starts = {}
for tg in r['thermal_generators']:
    ss = [t for t in range(T) if tg['startup'][t] == 1]
    if ss: starts[tg['name']] = ss
print('startup units:', starts)
